DROP POLICY avatar_owner_insert ON storage.objects;
CREATE POLICY avatar_owner_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'avatars' AND (storage.foldername(name))[1] = auth.uid()::text AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp','gif') AND (metadata IS NULL OR ((metadata->>'mimetype' IS NULL OR metadata->>'mimetype' IN ('image/jpeg','image/png','image/webp','image/gif')) AND (metadata->>'size' IS NULL OR (metadata->>'size')::bigint <= 2097152))));
DROP POLICY avatar_owner_update ON storage.objects;
CREATE POLICY avatar_owner_update ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'avatars' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'avatars' AND (storage.foldername(name))[1] = auth.uid()::text AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp','gif') AND (metadata IS NULL OR ((metadata->>'mimetype' IS NULL OR metadata->>'mimetype' IN ('image/jpeg','image/png','image/webp','image/gif')) AND (metadata->>'size' IS NULL OR (metadata->>'size')::bigint <= 2097152))));